	EX	DE,HL
	POP	DE
	POP	AF
	RET	Z
	OR	A
	SBC	HL,DE
	RET	NZ
	JR	CMOS_HUH
;
CMOS_DOT:	INC	HL
CMOS_DIR:	LD	A,'?'			;*DIR
	CALL	CMOS_SETUP
	CP	CMOS_CR
	JR	NZ,CMOS_HUH
	LD	C,17
CMOS_DIR0:	LD	B,4
CMOS_DIR1:	CALL	LTRAP
	LD	DE,CMOS_FCB
	LD	HL,CMOS_DSKBUF
	CALL	CMOS_SETDMA
	LD	A,C
	CALL	CMOS_BDOS1			;SEARCH DIRECTORY
	JP	M,CRLF
	RRCA
	RRCA
	RRCA
	AND	60H
	LD	E,A
	LD	D,0
	LD	HL,CMOS_DSKBUF+1
	ADD	HL,DE
	PUSH	HL
	LD	DE,8
	ADD	HL,DE
	LD	E,(HL)
	INC	HL
	BIT	7,(HL)			;SYSTEM FILE?
	POP	HL
	LD	C,18
	JR	NZ,CMOS_DIR1
	PUSH	BC
	LD	A,(CMOS_FCB)
	DEC	A
	LD	C,25
	CALL	M,CMOS_BDC
	ADD	A,'A'
	CALL	OSWRCH
	LD	B,8
	LD	A,' '
	BIT	7,E			;READ ONLY?
	JR	Z,CMOS_DIR3
	LD	A,'*'
CMOS_DIR3:	CALL	CMOS_CPTEXT
	LD	B,3
	LD	A,' '
	CALL	CMOS_SPTEXT
	POP	BC
	DJNZ	CMOS_DIR2
	CALL	CRLF
	JR	CMOS_DIR0
;
CMOS_DIR2:	PUSH	BC
	LD	B,5
CMOS_PAD:	LD	A,' '
	CALL	OSWRCH
	DJNZ	CMOS_PAD
	POP	BC
	JR	CMOS_DIR1
;
CMOS_OPT:	CALL	CMOS_HEX			;*OPT
	LD	A,E
	AND	3
CMOS_SETOPT:	LD	(CMOS_OPTVAL),A
	RET
;
RESET:	XOR	A
	JR	CMOS_SETOPT
;
CMOS_EXEC:	LD	A,00000001B		;*EXEC
	DEFB	1			;SKIP 2 BYTES (LD BC)
CMOS_SPOOL:	LD	A,00000010B		;*SPOOL
	PUSH	AF
	PUSH	HL
	CALL	CMOS_SESHUT			;STOP SPOOL/EXEC
	POP	HL
	POP	BC
	LD	A,(HL)
	CP	CMOS_CR			;JUST SHUT?
	RET	Z
	LD	A,(CMOS_FLAGS)
	OR	B
	LD	(CMOS_FLAGS),A		;SPOOL/EXEC FLAG
	RRA	;CARRY=1 FOR EXEC
	CALL	CMOS_OPENIT			;OPEN SPOOL/EXEC FILE
	RET	Z			;DIR FULL / NOT FOUND
	POP	IX			;RETURN ADDRESS
	LD	HL,(HIMEM)
	OR	A
	SBC	HL,SP			;SP=HIMEM?
	ADD	HL,SP
	JR	NZ,CMOS_JPIX			;ABORT
	LD	BC,-CMOS_FCBSIZ
	ADD	HL,BC			;HL=HL-FCBSIZ
	LD	(HIMEM),HL		;NEW HIMEM
	LD	(CMOS_TABLE),HL		;FCB/BUFFER
	LD	SP,HL			;NEW SP
	EX	DE,HL
	CALL	CMOS_OPEN3			;FINISH OPEN OPERATION
CMOS_JPIX:	JP	(IX)			;"RETURN"
;
CMOS_UPPRC:	AND	7FH
	CP	'`'
	RET	C
	AND	5FH			;CONVERT TO UPPER CASE
	RET
;
CMOS_HELP:	LD	B,32
	LD	HL,VERMSG
	JP	CMOS_PTEXT
;
;*ESC COMMAND
;
CMOS_ESCCTL:	LD	A,(HL)
	CALL	CMOS_UPPRC			;**
	CP	'O'
	JR	NZ,CMOS_ESCC1
	INC	HL
CMOS_ESCC1:	CALL	CMOS_HEX
	LD	A,E
	OR	A
	LD	HL,CMOS_FLAGS
	RES	6,(HL)			;ENABLE ESCAPE
	RET	Z
	SET	6,(HL)			;DISABLE ESCAPE
	RET
;
;
CMOS_COMDS:	DEFM	'BY'
	DEFB	'E'+80H
	DEFW	BYE
	DEFM	'DI'
	DEFB	'R'+80H
	DEFW	CMOS_DIR
	DEFM	'DRIV'
	DEFB	'E'+80H
	DEFW	CMOS_DRV
	DEFM	'ERAS'
	DEFB	'E'+80H
	DEFW	CMOS_ERA
	DEFM	'ER'
	DEFB	'A'+80H
	DEFW	CMOS_ERA
	DEFM	'ES'
	DEFB	'C'+80H
	DEFW	CMOS_ESCCTL
	DEFM	'EXE'
	DEFB	'C'+80H
	DEFW	CMOS_EXEC
	DEFM	'HEL'
	DEFB	'P'+80H
	DEFW	CMOS_HELP
	DEFM	'LOA'
	DEFB	'D'+80H
	DEFW	CMOS_STLOAD
	DEFM	'OP'
	DEFB	'T'+80H
	DEFW	CMOS_OPT
	DEFM	'QUI'
	DEFB	'T'+80H
	DEFW	BYE
	DEFM	'RENAM'
	DEFB	'E'+80H
	DEFW	CMOS_REN
	DEFM	'RE'
	DEFB	'N'+80H
	DEFW	CMOS_REN
	DEFM	'RESE'
	DEFB	'T'+80H
	DEFW	CMOS_RES
	DEFM	'SAV'
	DEFB	'E'+80H
	DEFW	CMOS_STSAVE
	DEFM	'SPOO'
	DEFB	'L'+80H
	DEFW	CMOS_SPOOL
	DEFM	'TYP'
	DEFB	'E'+80H
	DEFW	CMOS_TYPE
	DEFB	0FFH
;
;PTEXT - Print text
;   Inputs: HL = address of text
;            B = number of characters to print
; Destroys: A,B,H,L,F
;
CMOS_CPTEXT:	PUSH	AF
	LD	A,':'
	CALL	OSWRCH
	POP	AF
CMOS_SPTEXT:	CALL	OSWRCH
CMOS_PTEXT:	LD	A,(HL)
	AND	7FH
	INC	HL
	CALL	OSWRCH
	DJNZ	CMOS_PTEXT
	RET
;
;OSINIT - Initialise RAM mapping etc.
;If BASIC is entered by BBCBASIC FILENAME then file
;FILENAME.BBC is automatically CHAINed.
;   Outputs: DE = initial value of HIMEM (top of RAM)
;            HL = initial value of PAGE (user program)
;            Z-flag reset indicates AUTO-RUN.
;  Destroys: A,B,C,D,E,H,L,F
;
OSINIT:	LD	C,45			;*
	LD	E,254			;*
	CALL	CMOS_BDOS			;*
	XOR	A
	LD	B,CMOS_INILEN
	LD	HL,CMOS_TABLE
CMOS_CLRTAB:	LD	(HL),A			;CLEAR FILE TABLE ETC.
	INC	HL
	DJNZ	CMOS_CLRTAB
	LD	DE,ACCS
	LD	HL,CMOS_DSKBUF
	LD	C,(HL)
	INC	HL
	CP	C			;N.B. A=B=0
	JR	Z,CMOS_NOBOOT
	LDIR	;COPY TO ACCS
CMOS_NOBOOT:	EX	DE,HL
	LD	(HL),CMOS_CR
	LD	DE,(6)			;DE = HIMEM
	LD	E,A			;PAGE BOUNDARY
	LD	HL,USER
	RET
;
;
;TRAP - Test ESCAPE flag and abort if set;
;       every 20th call, test for keypress.
; Destroys: A,H,L,F
;
;LTRAP - Test ESCAPE flag and abort if set.
; Destroys: A,F
;
TRAP:	LD	HL,CMOS_TRPCNT
	DEC	(HL)
	CALL	Z,CMOS_TEST20		;TEST KEYBOARD
LTRAP:	LD	A,(CMOS_FLAGS)		;ESCAPE FLAG
	OR	A			;TEST
	RET	P
CMOS_ABORT:	LD	HL,CMOS_FLAGS		;ACKNOWLEDGE
	RES	7,(HL)			;ESCAPE
	JP	ESCAPE			;AND ABORT
;
;TEST - Sample for ESCape and CTRL/S. If ESCape
;       pressed set ESCAPE flag and return.
; Destroys: A,F
;
CMOS_TEST20:	LD	(HL),20
CMOS_TEST:	PUSH	DE
	LD	A,6
	LD	E,0FFH
	CALL	CMOS_BDOS0
	POP	DE
	OR	A
	RET	Z
	CP	'S' AND 1FH		;PAUSE DISPLAY?
	JR	Z,OSRDCH
	CP	CMOS_ESC
	JR	Z,CMOS_ESCSET
	LD	(CMOS_INKEY),A
	RET
;
;OSRDCH - Read from the current input stream (keyboard).
;  Outputs: A = character
; Destroys: A,F
;
CMOS_KEYGET:	LD	B,(IX-12)		;SCREEN WIDTH
	CALL	OSRDCH
	CP	CMOS_DEL
	JR	Z,CMOS_KEYDEL
	CP	224
	RET	NZ
	CALL	OSRDCH
	SUB	65
	RET
;
CMOS_KEYDEL:	LD	A,CMOS_BS
	RET
;
OSRDCH:	LD	A,(CMOS_FLAGS)
	RRA	;*EXEC ACTIVE?
	JR	C,CMOS_EXECIN
	PUSH	HL
	SBC	HL,HL			;HL=0
	CALL	OSKEY
	POP	HL
	RET	C
	JR	OSRDCH
;
;EXECIN - Read byte from EXEC file
;  Outputs: A = byte read
; Destroys: A,F
;
CMOS_EXECIN:	PUSH	BC			;SAVE REGISTERS
	PUSH	DE
	PUSH	HL
	LD	E,8			;SPOOL/EXEC CHANNEL
	LD	HL,CMOS_FLAGS
	RES	0,(HL)
	CALL	OSBGET
	SET	0,(HL)
	PUSH	AF
	CALL	C,CMOS_SESHUT		;END EXEC IF EOF
	POP	AF
	POP	HL			;RESTORE REGISTERS
	POP	DE
	POP	BC
	RET
;
;
;OSKEY - Read key with time-limit, test for ESCape.
;Main function is carried out in user patch.
;   Inputs: HL = time limit (centiseconds)
;  Outputs: Carry reset if time-out
;           If carry set A = character
; Destroys: A,H,L,F
;
OSKEY:	PUSH	HL
	LD	HL,CMOS_INKEY
	LD	A,(HL)
	LD	(HL),0
	POP	HL
	OR	A
	SCF
	RET	NZ
	PUSH	DE
	CALL	GETKEY
	POP	DE
	RET	NC
	CP	CMOS_ESC
	SCF
	RET	NZ
CMOS_ESCSET:	PUSH	HL
	LD	HL,CMOS_FLAGS
	BIT	6,(HL)			;ESC DISABLED?
	JR	NZ,CMOS_ESCDIS
	SET	7,(HL)			;SET ESCAPE FLAG
CMOS_ESCDIS:	POP	HL
	RET
;
;OSWRCH - Write a character to console output.
;   Inputs: A = character.
; Destroys: Nothing
;
OSWRCH:	PUSH	AF
	PUSH	DE
	PUSH	HL
	LD	E,A
	CALL	CMOS_TEST
	CALL	CMOS_EDPUT
	POP	HL
	POP	DE
	POP	AF
	RET
;
CMOS_EDPUT:	LD	A,(CMOS_FLAGS)
	BIT	3,A
	JR	Z,CMOS_WRCH
	LD	A,E
	CP	' '
	RET	C
	LD	HL,(CMOS_EDPTR)
	LD	(HL),E
	INC	L
	RET	Z
	LD	(CMOS_EDPTR),HL
	RET
;
PROMPT:	LD	E,'>'
CMOS_WRCH:	LD	A,(CMOS_OPTVAL)		;FAST ENTRY
	ADD	A,3
	CP	3
	JR	NZ,CMOS_WRCH1
	ADD	A,E
	LD	A,2
	JR	C,CMOS_WRCH1
	LD	A,6
CMOS_WRCH1:	CALL	CMOS_BDOS0
	LD	HL,CMOS_FLAGS
	BIT	2,(HL)
	LD	A,5			;PRINTER O/P
	CALL	NZ,CMOS_BDOS0
	BIT	1,(HL)			;SPOOLING?
	RET	Z
	RES	1,(HL)
	LD	A,E			;BYTE TO WRITE
	LD	E,8			;SPOOL/EXEC CHANNEL
	PUSH	BC
	CALL	OSBPUT
	POP	BC
	SET	1,(HL)
	RET
;
CMOS_TOGGLE:	LD	BC,0
	LD	A,(CMOS_FLAGS)
	XOR	00000100B
	LD	(CMOS_FLAGS),A
	RET
;
CMOS_INSERT:	LD	A,(CMOS_FLAGS)
	XOR	00010000B
	LD	(CMOS_FLAGS),A
	RET
;
;OSLINE - Read/edit a complete line, terminated by CR.
;   Inputs: HL addresses destination buffer.
;           (L=0)
;  Outputs: Buffer filled, terminated by CR.
;           A=0.
; Destroys: A,B,C,D,E,H,L,F
;
OSLINE:	LD	IX,200H
	LD	A,(CMOS_FLAGS)
	BIT	3,A			;EDIT MODE?
	JR	Z,CMOS_OSLIN1
	RES	3,A
	LD	(CMOS_FLAGS),A
	LD	HL,(CMOS_EDPTR)
	CP	L
CMOS_OSLIN1:	LD	A,CMOS_CR
	LD	(HL),A
	CALL	NZ,OSWRCH
	LD	L,0
	LD	C,L			;REPEAT FLAG
	JR	Z,CMOS_OSWAIT		;SUPPRESS UNWANTED SPACE
CMOS_UPDATE:	LD	B,0
CMOS_UPD1:	LD	A,(HL)
	INC	B
	INC	HL
	CP	CMOS_CR
	PUSH	AF
	PUSH	HL
	LD	E,A
	CALL	NZ,CMOS_WRCH			;FAST WRCH
	POP	HL
	POP	AF
	JR	NZ,CMOS_UPD1
	LD	A,' '
	CALL	OSWRCH
	LD	E,CMOS_BS
CMOS_UPD2:	PUSH	HL
	CALL	CMOS_WRCH			;FAST WRCH
	POP	HL
	DEC	HL
	DJNZ	CMOS_UPD2
CMOS_OSWAIT:	LD	A,C
	DEC	B
	JR	Z,CMOS_LIMIT
	OR	A			;REPEAT COMMAND?
CMOS_LIMIT:	CALL	Z,CMOS_KEYGET		;READ KEYBOARD
	LD	C,A			;SAVE FOR REPEAT
	LD	DE,CMOS_OSWAIT		;RETURN ADDRESS
	PUSH	DE
	LD	A,(CMOS_FLAGS)
	OR	A			;TEST FOR ESCAPE
	LD	A,C
	JP	M,CMOS_OSEXIT
	CP	'P' AND 1FH
	JP	Z,CMOS_TOGGLE
	CP	(IX-11)			;CURSOR UP     (IX-11)
	JP	Z,CMOS_LEFT
	CP	(IX-10)			;CURSOR DOWN   (IX-10)
	JP	Z,CMOS_RIGHT
	LD	B,0
	CP	(IX-5)			;CLEAR LEFT    (IX-5)
	JR	Z,CMOS_BACK
	CP	(IX-9)			;START OF LINE (IX-9)
	JR	Z,CMOS_LEFT
	CP	(IX-8)			;END OF LINE   (IX-8)
	JP	Z,CMOS_RIGHT
	CP	(IX-7)			;CLEAR RIGHT   (IX-7)
	JR	Z,CMOS_DELETE
	LD	C,0			;INHIBIT REPEAT
	CP	(IX-1)			;INSERT / OVR  (IX-1)
	JP	Z,CMOS_INSERT
	CP	(IX-6)			;DELETE LEFT   (IX-6)
	JR	Z,CMOS_BACK
	CP	(IX-4)			;CURSOR LEFT   (IX-4)
	JR	Z,CMOS_LEFT
	CP	(IX-2)			;DELETE RIGHT  (IX-2)
	JR	Z,CMOS_DELETE
	CP	(IX-3)			;CURSOR RIGHT  (IX-3)
	JP	Z,CMOS_RIGHT
	CP	' '			;PRINTING CHARACTER
	JR	NC,CMOS_SAVECH
	CP	CMOS_CR			;ENTER LINE
	RET	NZ
CMOS_OSEXIT:	LD	A,(HL)
	CALL	OSWRCH			;WRITE REST OF LINE
	INC	HL
	SUB	CMOS_CR
	JR	NZ,CMOS_OSEXIT
	POP	DE			;DITCH RETURN ADDRESS
	CP	C
	JP	NZ,CMOS_ABORT		;ESCAPE
	LD	A,CMOS_LF
	CALL	OSWRCH
	XOR	A
	LD	L,A
	LD	(CMOS_EDPTR),HL
	LD	DE,(CURLIN)
	CP	D
	RET	NZ
	CP	E
	RET	NZ
	LD	DE,(AUTONO)
	CP	D
	RET	NZ
	CP	E
	RET	NZ
	LD	DE,CMOS_EDITST
	LD	B,4
CMOS_CMPARE:	LD	A,(DE)
	CP	(HL)
	LD	A,0
	RET	NZ
	INC	HL
	INC	DE
	LD	A,(HL)
	CP	'.'
	JR	Z,CMOS_ABBR
	DJNZ	CMOS_CMPARE
CMOS_ABBR:	XOR	A
	LD	B,A
	LD	C,L
	LD	L,A
	LD	DE,CMOS_LISTST
	EX	DE,HL
	LDIR
	LD	HL,CMOS_FLAGS
	SET	3,(HL)
	RET
;
CMOS_BACK:	SCF	;DELETE LEFT
CMOS_LEFT:	INC	L			;CURSOR LEFT
	DEC	L
	JR	Z,CMOS_STOP
	LD	A,CMOS_BS
	CALL	OSWRCH
	DEC	L
	RET	NC
CMOS_DELETE:	LD	A,(HL)			;DELETE RIGHT
	CP	CMOS_CR
	JR	Z,CMOS_STOP
	LD	D,H
	LD	E,L
CMOS_DEL1:	INC	DE
	LD	A,(DE)
	DEC	DE
	LD	(DE),A
	INC	DE
	CP	CMOS_CR
	JR	NZ,CMOS_DEL1
CMOS_DEL2:	POP	DE			;DITCH
	JP	CMOS_UPDATE
;
CMOS_SAVECH:	LD	D,A
	LD	A,(CMOS_FLAGS)
	AND	00010000B
	LD	A,D
	JR	NZ,CMOS_RIGHT1
	LD	D,A
	LD	A,CMOS_CR			;INSERT SPACE
	CP	(HL)
	LD	A,D
	JR	Z,CMOS_RIGHT1
	LD	D,H
	LD	E,254
	PUSH	AF
CMOS_INS1:	INC	DE
	LD	(DE),A
	DEC	DE
	LD	A,E
	CP	L
	DEC	DE
	LD	A,(DE)
	JR	NZ,CMOS_INS1
	POP	AF
	LD	(HL),A
	INC	L
	JR	Z,CMOS_WONTGO
	CALL	OSWRCH
	JR	CMOS_DEL2
;
CMOS_RIGHT:	LD	A,(HL)			;CURSOR RIGHT
	CP	CMOS_CR
	JR	Z,CMOS_STOP
CMOS_RIGHT1:	LD	D,(HL)			;PRINTING CHARACTER
	LD	(HL),A
	INC	L
	JR	Z,CMOS_WONTGO		;LINE TOO LONG
	CALL	OSWRCH
	LD	A,CMOS_CR
	CP	D
	RET	NZ
	LD	(HL),A
	RET
;
CMOS_WONTGO:	DEC	L
	LD	(HL),CMOS_CR
	LD	A,CMOS_BEL
	CALL	OSWRCH			;BEEP!
CMOS_STOP:	LD	C,0			;STOP REPEAT
	RET
;
;
CMOS_EDITST:	DEFM	'EDIT'
CMOS_LISTST:	DEFM	'LIST'
;
CMOS_BEL:	EQU	7
CMOS_BS:	EQU	8
CMOS_HT:	EQU	9
CMOS_LF:	EQU	0AH
CMOS_VT:	EQU	0BH
CMOS_CR:	EQU	0DH
CMOS_ESC:	EQU	1BH
CMOS_DEL:	EQU	7FH
;
CMOS_BDOS:	EQU	5
;
CMOS_FCB:	EQU	5CH
CMOS_DSKBUF:	EQU	80H
;
CMOS_FCBSIZ:	EQU	128+36+2
;
CMOS_TRPCNT:	DEFB	10
CMOS_TABLE:	DEFS	16			;FILE BLOCK POINTERS
CMOS_FLAGS:	DEFB	0
CMOS_INKEY:	DEFB	0
CMOS_EDPTR:	DEFW	0
CMOS_OPTVAL:	DEFB	0
CMOS_INILEN:	EQU	$-CMOS_TABLE
;
CMOS_FIN:

